frappe.ui.form.on('Transfer Certificate Request', {
	admission_no: function (frm) {
		if (!frm.doc.admission_no) return;

		frappe.db.get_doc('Student', frm.doc.admission_no)
			.then(student => {
				frm.set_value('name_of_the_student', student.student_name);
				frm.set_value('gender', student.gender);
				frm.set_value('udise_pen', student.uidai_no);
				frm.set_value('dob_figures', student.date_of_birth);
				frm.set_value('dob_words', convertDateToWords(student.date_of_birth));
				frm.set_value('nationality', student.nationality);
				frm.set_value('category', student.category);
				frm.set_value('date_of_joining', student.joining_date);

			    // Get values from Student Logs child table
                if (student.student_logs && student.student_logs.length > 0) {
                	const latest_log = student.student_logs[student.student_logs.length - 1];

                	// Set values to main form fields
                	frm.set_value('previous_school_attended', latest_log.prvious_school_attended);
                	frm.set_value('course_attended_in_the_previous_school', latest_log.grade_qualified);
                }


				// Set guardian names
				if (student.guardians?.length) {
					student.guardians.forEach(g => {
						if (g.relation === 'Father') frm.set_value('name_of_father', g.guardian_name);
						if (g.relation === 'Mother') frm.set_value('name_of_mother', g.guardian_name);
					});
				}

				// Get the latest Program Enrollment
				frappe.db.get_list('Program Enrollment', {
					filters: { student: student.name },
					fields: ['name', 'academic_year', 'program'],
					order_by: 'creation desc',
					limit: 1
				}).then(pe_list => {
					if (pe_list.length > 0) {
						let pe = pe_list[0];
						frm.set_value('ay_figures', pe.academic_year);
						frm.set_value('course_last_attended', pe.program);
						frm.set_value('ay_words', convertYearToFullWords(pe.academic_year));

						// Fetch full Program Enrollment document with child table
						frappe.db.get_doc('Program Enrollment', pe.name)
							.then(full_pe => {
								if (full_pe.courses && full_pe.courses.length > 0) {
									// Clear existing rows in Transfer Certificate child table
									frm.clear_table('subjects_studied');

									// Copy each course into the Transfer Certificate child table
									full_pe.courses.forEach(course => {
										let row = frm.add_child('subjects_studied');
										row.course = course.course;
										row.course_name = course.course_name;
									});

									frm.refresh_field('subjects_studied');
								}
							});
					}
				});
			})
			.catch(err => {
				console.error(err);
				frappe.msgprint(__('Unable to fetch Student Info.'));
			});
	}
});

// Function to convert the date into full words (e.g., TWENTY SEVENTH MAY TWO THOUSAND FOURTEEN)
function convertDateToWords(date) {
	const dateObj = new Date(date);
	const day = dateObj.getDate();
	const month = dateObj.toLocaleString('default', { month: 'long' }).toUpperCase();
	const year = dateObj.getFullYear();

	const dayInWords = convertDayToWords(day);
	const yearInWords = convertYearToWords(year);

	return `${dayInWords} ${month} ${yearInWords}`;
}

// Function to convert the day to words
function convertDayToWords(day) {
	const words = [
		'FIRST', 'SECOND', 'THIRD', 'FOURTH', 'FIFTH', 'SIXTH', 'SEVENTH', 'EIGHTH', 'NINTH', 'TENTH',
		'ELEVENTH', 'TWELFTH', 'THIRTEENTH', 'FOURTEENTH', 'FIFTEENTH', 'SIXTEENTH', 'SEVENTEENTH',
		'EIGHTEENTH', 'NINETEENTH', 'TWENTIETH', 'TWENTY FIRST', 'TWENTY SECOND', 'TWENTY THIRD', 
		'TWENTY FOURTH', 'TWENTY FIFTH', 'TWENTY SIXTH', 'TWENTY SEVENTH', 'TWENTY EIGHTH', 'TWENTY NINTH',
		'THIRTIETH', 'THIRTY FIRST'
	];
	return words[day - 1];
}

// Function to convert the year for DOB (e.g., TWO THOUSAND FOURTEEN)
function convertYearToWords(year) {
	const ones = ['', 'ONE', 'TWO', 'THREE', 'FOUR', 'FIVE', 'SIX', 'SEVEN', 'EIGHT', 'NINE'];
	const teens = ['TEN', 'ELEVEN', 'TWELVE', 'THIRTEEN', 'FOURTEEN', 'FIFTEEN', 'SIXTEEN', 'SEVENTEEN', 'EIGHTEEN', 'NINETEEN'];
	const tens = ['', '', 'TWENTY', 'THIRTY', 'FORTY', 'FIFTY', 'SIXTY', 'SEVENTY', 'EIGHTY', 'NINETY'];

	const strYear = year.toString();
	let words = '';

	words += `${ones[parseInt(strYear[0])]} THOUSAND `;

	const secondPair = parseInt(strYear[1] + strYear[2]);
	if (secondPair < 10) {
		words += `${ones[secondPair]} `;
	} else if (secondPair < 20) {
		words += `${teens[secondPair - 10]} `;
	} else {
		words += `${tens[Math.floor(secondPair / 10)]} `;
		if (secondPair % 10 !== 0) {
			words += `${ones[secondPair % 10]} `;
		}
	}

	words += ones[parseInt(strYear[3])];
	return words.trim();
}

// Function to convert year like 2026 to "TWO THOUSAND TWENTY SIX"
function convertYearToFullWords(year) {
	const ones = ['', 'ONE', 'TWO', 'THREE', 'FOUR', 'FIVE', 'SIX', 'SEVEN', 'EIGHT', 'NINE'];
	const teens = ['TEN', 'ELEVEN', 'TWELVE', 'THIRTEEN', 'FOURTEEN', 'FIFTEEN', 'SIXTEEN', 'SEVENTEEN', 'EIGHTEEN', 'NINETEEN'];
	const tens = ['', '', 'TWENTY', 'THIRTY', 'FORTY', 'FIFTY', 'SIXTY', 'SEVENTY', 'EIGHTY', 'NINETY'];

	let num = parseInt(year, 10);
	let words = '';

	if (num >= 2000 && num < 3000) {
		words = 'TWO THOUSAND';
		const lastTwoDigits = num % 100;

		if (lastTwoDigits > 0) {
			words += ' ';
			if (lastTwoDigits < 10) {
				words += ones[lastTwoDigits];
			} else if (lastTwoDigits < 20) {
				words += teens[lastTwoDigits - 10];
			} else {
				words += tens[Math.floor(lastTwoDigits / 10)];
				if (lastTwoDigits % 10 !== 0) {
					words += ' ' + ones[lastTwoDigits % 10];
				}
			}
		}
	}
	return words;
}
